const ALLOWED_CATEGORY  = ["Recruitment", "Support", "Sales", "Other"];
const ALLOWED_SENTIMENT = ["Positive", "Neutral", "Negative"];
const ALLOWED_PRIORITY  = ["High", "Medium", "Low"];

function extractJson(raw) {
  if (raw == null) return null;
  if (typeof raw === "object") return raw;
  let s = String(raw).trim();
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/i, "").trim();
  try { return JSON.parse(s); } catch (_) {}
  // Last resort: grab the first {...} block
  const m = s.match(/\{[\s\S]*\}/);
  if (m) {
    try { return JSON.parse(m[0]); } catch (_) {}
  }
  return null;
}

function pickEnum(value, allowed, fallback) {
  if (typeof value !== "string") return fallback;
  const hit = allowed.find(a => a.toLowerCase() === value.trim().toLowerCase());
  return hit || fallback;
}

const ticket = $("Process One By One").item.json;


const resp = $input.item.json;
const textPart = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
const finishReason = resp?.candidates?.[0]?.finishReason;
const raw =
  $json.DEBUG_text ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  $json.text ||
  $json.output ||
  null;

let parsed = extractJson(textPart);
let aiError = null;

if (!parsed) {
  aiError = `Could not parse Gemini response (finishReason=${finishReason ?? "unknown"})`;
  parsed = {};
}

const analysis = {
  category:  pickEnum(parsed.category,  ALLOWED_CATEGORY,  "Other"),
  sentiment: pickEnum(parsed.sentiment, ALLOWED_SENTIMENT, "Neutral"),
  priority:  pickEnum(parsed.priority,  ALLOWED_PRIORITY,  "Low"),
  reasoning: typeof parsed.reasoning === "string" ? parsed.reasoning : "",
};

return [{
  json: {
    // Original ticket fields
    name:    ticket.name,
    surname: ticket.surname,
    email:   ticket.email,
    message: ticket.message,
    ingested_at: ticket.ingested_at,
    // AI analysis
    ...analysis,
    // Meta
    model: "gemini-2.5-flash",
    analyzed_at: new Date().toISOString(),
  }
}]

// Convert the current item to a single-line JSON + newline (JSONL format)
// and expose it as binary data for the Read/Write Files node to append.
const line = JSON.stringify($json) + "\n";
const binary = await this.helpers.prepareBinaryData(Buffer.from(line, "utf8"), "ticket.jsonl", "application/x-ndjson");
return [{ json: $json, binary: { data: binary } }];
